/**
 * Demo catalogue. Audio = free SoundHelix sample MP3s (https://www.soundhelix.com/audio-examples),
 * cover art = original gradient SVGs generated by scripts/generate-covers.mjs.
 * Artists/titles are fictional.
 */
import type { Artist, Playlist, Track } from "./models";

const AUDIO = (n: number) => `https://www.soundhelix.com/examples/mp3/SoundHelix-Song-${n}.mp3`;

const t = (
  n: number,
  slug: string,
  title: string,
  artist: string,
  album: string,
  durationMs: number,
): Track => ({
  id: String(n),
  uri: `demo:track:${n}`,
  title,
  artist,
  album,
  image: `/covers/${slug}.svg`,
  durationMs,
  audioUrl: AUDIO(n),
});

export const MOCK_TRACKS: Track[] = [
  t(1, "midnight-circuits", "Midnight Circuits", "Aurora Vale", "Neon Atlas", 372_000),
  t(2, "low-light", "Low Light", "Kite & Cassette", "Velvet Static", 425_000),
  t(3, "glass-hours", "Glass Hours", "Nova Parade", "Prism Season", 345_000),
  t(4, "afterglow-protocol", "Afterglow Protocol", "Halcyon Ghost", "Signal Bloom", 302_000),
  t(5, "paper-satellites", "Paper Satellites", "Marlo Quinn", "Orbit Letters", 307_000),
  t(6, "slow-violet", "Slow Violet", "Lune Atlas", "Dusk Theory", 345_000),
  t(7, "heat-haze", "Heat Haze", "The Parallel Days", "Mirage Hours", 395_000),
  t(8, "cold-open", "Cold Open", "Sable Park", "Quiet Frames", 244_000),
  t(9, "static-bloom", "Static Bloom", "Aurora Vale", "Neon Atlas", 350_000),
  t(10, "last-train", "Last Train to Neon", "Halcyon Ghost", "Signal Bloom", 326_000),
];

const byId = (...ids: number[]) => ids.map((id) => MOCK_TRACKS.find((x) => x.id === String(id))!);

export const MOCK_ARTISTS: Artist[] = Array.from(new Set(MOCK_TRACKS.map((x) => x.artist))).map((name, i) => {
  const first = MOCK_TRACKS.find((x) => x.artist === name)!;
  return { id: `a${i}`, uri: `demo:artist:${i}`, name, image: first.image };
});

export interface MockPlaylist extends Playlist {
  tracks: Track[];
}

const mp = (id: string, name: string, description: string, tracks: Track[]): MockPlaylist => ({
  id,
  uri: `demo:playlist:${id}`,
  name,
  description,
  owner: "Pulse Demo",
  image: tracks[0].image,
  total: tracks.length,
  tracks,
});

export const MOCK_PLAYLISTS: MockPlaylist[] = [
  mp("late-night-neon", "Late Night Neon", "Synths, city lights, 2 a.m.", byId(1, 2, 4, 10, 7)),
  mp("focus-flow", "Focus Flow", "Steady and distraction-free.", byId(3, 5, 6, 8)),
  mp("heavy-rotation", "Heavy Rotation", "The ones on repeat.", byId(9, 1, 4, 6, 2, 10)),
  mp("after-hours", "After Hours", "Wind down slowly.", byId(9, 6, 2)),
];

export const MOCK_USER = { name: "Guest Listener", image: null as string | null };
